ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS grace_days integer NOT NULL DEFAULT 3 CHECK(grace_days>=0 AND grace_days<=365);
CREATE OR REPLACE FUNCTION public.set_metrics_settings(_grace_days integer,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_row jsonb; new_row jsonb; BEGIN PERFORM public._assert_admin_writer(); PERFORM public._assert_reason(_reason); IF _grace_days IS NULL OR _grace_days NOT BETWEEN 0 AND 365 THEN RAISE EXCEPTION 'فترة السماح غير صالحة'; END IF; SELECT to_jsonb(s) INTO old_row FROM public.app_settings s ORDER BY id LIMIT 1 FOR UPDATE; IF old_row IS NULL THEN RAISE EXCEPTION 'إعدادات المشروع غير موجودة'; END IF; UPDATE public.app_settings SET grace_days=_grace_days,updated_at=now(),updated_by=auth.uid() WHERE id=(old_row->>'id')::integer RETURNING to_jsonb(app_settings) INTO new_row; PERFORM public._safety_audit('METRICS_SETTINGS','app_settings',old_row->>'id',old_row,new_row,_reason); END $$;
REVOKE ALL ON FUNCTION public.set_metrics_settings(integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_metrics_settings(integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.metrics_ratio(_numerator numeric,_denominator numeric) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN _denominator>0 THEN round(100*_numerator/_denominator,2) ELSE NULL END $$;
CREATE OR REPLACE FUNCTION public.metrics_is_overdue(_due date,_today date,_grace integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT _due < _today-_grace $$;
CREATE OR REPLACE VIEW public.metrics_unit_scope WITH(security_invoker=true) AS SELECT u.id,u.unit_number,u.building_number,u.building_id,b.phase,u.activity_id,a.name_ar AS activity_name,u.unit_type,u.publish_state,u.leasing_status,u.area_m2,u.updated_at FROM public.units u LEFT JOIN public.buildings b ON b.id=u.building_id LEFT JOIN public.activities a ON a.id=u.activity_id WHERE NOT u.is_test;
CREATE OR REPLACE VIEW public.metrics_installment_balances WITH(security_invoker=true) AS SELECT i.*,c.party_id,c.status AS contract_status,coalesce(p.paid_excl,0) AS paid_excl,coalesce(p.paid_vat,0) AS paid_vat,greatest(0,i.amount_excl_vat-coalesce(p.paid_excl,0)) AS remaining_excl,greatest(0,i.vat_amount-coalesce(p.paid_vat,0)) AS remaining_vat FROM public.installments i JOIN public.contracts c ON c.id=i.contract_id LEFT JOIN LATERAL(SELECT sum(a.amount_excl_vat) AS paid_excl,sum(a.vat_amount) AS paid_vat FROM public.receipt_allocations a JOIN public.receipt_cash_read r ON r.id=a.receipt_id WHERE a.installment_id=i.id AND a.reverses_id IS NULL AND r.status='verified' AND r.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipts rev WHERE rev.reverses_id=r.id)) p ON true WHERE i.status<>'waived' AND c.status IN('active','ended','terminated');
CREATE OR REPLACE VIEW public.metrics_receipt_scope WITH(security_invoker=true) AS SELECT r.id,r.receipt_no,r.paid_at,r.contract_id,r.amount_excl_vat,r.vat_amount,r.amount_incl_vat,r.vat_documented,r.status,coalesce(p.allocated_excl,0) AS allocated_excl,coalesce(p.allocated_vat,0) AS allocated_vat FROM public.receipt_cash_read r LEFT JOIN LATERAL(SELECT sum(a.amount_excl_vat) AS allocated_excl,sum(a.vat_amount) AS allocated_vat FROM public.receipt_allocations a WHERE a.receipt_id=r.id AND a.reverses_id IS NULL) p ON true WHERE r.status='verified' AND r.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipts rev WHERE rev.reverses_id=r.id);
CREATE OR REPLACE VIEW public.metrics_conversion_events WITH(security_invoker=true) AS SELECT a.entity_id::uuid AS opportunity_id,a.created_at AS reached_at,a.id AS event_id FROM public.audit_log a WHERE a.entity_table='opportunities' AND a.entity_id ~ '^[0-9a-fA-F-]{36}$' AND a.before_data IS NOT NULL AND a.before_data->>'stage' IS DISTINCT FROM 'pending_contract' AND a.after_data->>'stage'='pending_contract' AND a.action IN('OPPORTUNITY_STAGE','MOVE_OPPORTUNITY','UPDATE','OPPORTUNITY_STAGE_CHANGED');
REVOKE ALL ON public.metrics_unit_scope,public.metrics_installment_balances,public.metrics_receipt_scope,public.metrics_conversion_events FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.metrics_unit_scope,public.metrics_installment_balances,public.metrics_receipt_scope,public.metrics_conversion_events TO service_role;
CREATE OR REPLACE FUNCTION public.metrics_scope_match(_unit public.metrics_unit_scope,_scope jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT (nullif(_scope->>'building','') IS NULL OR _unit.building_number::text=_scope->>'building') AND (nullif(_scope->>'phase','') IS NULL OR CASE WHEN _scope->>'phase'='unassigned' THEN _unit.phase IS NULL ELSE _unit.phase::text=_scope->>'phase' END) AND (nullif(_scope->>'activity','') IS NULL OR CASE WHEN _scope->>'activity'='unassigned' THEN _unit.activity_id IS NULL ELSE _unit.activity_id::text=_scope->>'activity' END) AND (nullif(_scope->>'unit_type','') IS NULL OR _unit.unit_type=_scope->>'unit_type') $$;
REVOKE ALL ON FUNCTION public.metrics_scope_match(public.metrics_unit_scope,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.metrics_scope_match(public.metrics_unit_scope,jsonb) TO service_role;
SELECT to_regclass('public.metrics_unit_scope') IS NOT NULL AS scope_ready,to_regclass('public.metrics_installment_balances') IS NOT NULL AS balances_ready,public.metrics_is_overdue(date '2026-11-02',date '2026-11-05',3)=false AS grace_boundary_ok,public.metrics_is_overdue(date '2026-11-01',date '2026-11-05',3)=true AS grace_after_ok,public.metrics_ratio(1,0) IS NULL AS zero_denominator_ok;